insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9253, 25, 'Durchsetzung der Pflichten von Plattformen zur Entfernung rechtswidriger Inhalte (DSA) stärken (Bund)', 'Eine Studie zum NetzDG zeigt weniger Hassbeiträge und weniger Hassdelikte durch Löschpflichten. Dagegen: Die Aufsicht über sehr große Plattformen liegt bei der EU-Kommission, der Bund stärkt vor allem die nationale Aufsicht.', 'belegt', 'https://econpapers.repec.org/RePEc:cge:wacage:701', 'bund', null, true, 'blind'),
  (9254, 25, 'Digitales Gewaltschutzgesetz mit gerichtlicher Accountsperre und Rechten für Betroffene (Bund)', 'Gibt Betroffenen Auskunfts- und Sperransprüche gegen Täter-Accounts und erleichtert das Löschen; ein Referentenentwurf liegt vor. Dagegen: Wirkung noch unerprobt, neue Accounts lassen sich leicht anlegen.', 'offen', null, 'bund', null, true, 'blind'),
  (9255, 25, 'Beratung und Unterstützung für Betroffene digitaler Gewalt ausbauen (Land)', 'Spezialisierte Beratung hilft Betroffenen, Hass zu melden, anzuzeigen und durchzustehen; Länder können sie selbst fördern. Dagegen: Wirkung auf Meldequote und Ausmaß des Hasses kaum evaluiert.', 'offen', null, 'land', null, true, 'blind'),
  (9256, 25, 'Medienbildung und digitale Prävention gegen Hass im Netz (Land)', 'Schulische Präventionsprogramme senken Cybermobbing leicht. Dagegen: Eine systematische Übersicht findet für Online-Maßnahmen gegen Hassrede bisher keinen gesicherten Effekt; Wirkung indirekt und langfristig.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9133687/', 'land', null, true, 'blind')
