insert into public.abdeckung (thema_id, partei_id, land, art, begruendung, stand, ki_entwurf, durchsucht_fuer) values
  (25, 11, null, 'keine', 'Kapitel Innere Sicherheit/Sicherheit im digitalen Raum (S. 38-41) und Fundstellen S. 39, 40, 41, 45, 46, 63 gelesen; nichts zu Hass, Bedrohung oder Anfeindung im Netz (nur IP-Speicherung, Cyberabwehr, DSA-Schwerpunkt Desinformation/Jugendschutz).', '2026-10-08', true, '{2501,2502,2503}'),
  (25, 11, 'BE', 'massnahmen', null, '2026-10-08', true, '{2501,2503}'),
  (25, 11, 'MV', 'massnahmen', null, '2026-10-08', true, '{2501,2503}'),
  (25, 11, 'ST', 'keine', 'Kapitel Medien (S. 34-37), Sicherheit (S. 8-9) und alle Fundstellen (S. 19, 22, 32, 35, 36, 58-60) gelesen; keine Zusage gegen Hass im Netz zu Meldewegen/Hilfe für Betroffene oder Prävention/Gesprächsdesign. Nur Medienkompetenz allgemein, Jugendmedienschutz, Plattformverantwortung allgemein.', '2026-10-08', true, '{2501,2503}'),
  (25, 12, null, 'massnahmen', null, '2026-10-08', true, '{2501,2502,2503}'),
