  (25, 13, 'ST', 'keine', 'Erfasste Stellen (S. 46) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-08', true, '{2501,2503}'),
  (25, 14, null, 'keine', 'Inhaltsverzeichnis, Kapitel Bildung (S. 9), Sicherheit und Bürgerrechte (S. 23-24), Gleichbehandlung (S. 25), Meinungsfreiheit (S. 27) und Fundstelle S. 49 gelesen; keine Zusage gegen Hass oder Anfeindung im Netz (nur Hasskriminalität allgemein, Medienkompetenz allgemein, DSA nur als Begrenzung).', '2026-10-08', true, '{2501,2502,2503}'),
  (25, 14, 'BE', 'massnahmen', null, '2026-10-08', true, '{2501,2503}'),
  (25, 14, 'MV', 'keine', 'Fundstellen S. 53, 95, 136-139, 146, 151 sowie Kapitel Schule (S. 87) und Rechtsstaatlichkeit/Meinungsfreiheit (S. 151) gelesen; nichts setzt an den Landesursachen 2501 oder 2503 an.', '2026-10-08', true, '{2501,2503}'),
  (25, 14, 'ST', 'keine', 'Erfasste Stellen (S. 26) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-08', true, '{2501,2503}'),
  (25, 15, null, 'massnahmen', null, '2026-10-08', true, '{2501,2502,2503}'),
  (25, 15, 'BE', 'massnahmen', null, '2026-10-08', true, '{2501,2503}'),
  (25, 15, 'MV', 'keine', 'Kapitel Sicherheit/Justiz (S. 42-44), Freiheitsland MV (S. 47) und Fundstellen S. 43, 44, 47, 53 gelesen; keine Zusage zu Hass, Bedrohung oder Anfeindung im Netz, zu Meldewegen, Betroffenenhilfe oder Plattformen. Stichwort Cybercrime nur allgemein (LKA-Personal).', '2026-10-08', true, '{2501,2503}'),
