  (25, 17, null, 'massnahmen', null, '2026-10-08', true, '{2501,2502,2503}'),
  (25, 17, 'BE', 'keine', 'Inhaltsverzeichnis, Kapitel Schule/Medienbildung (S. 16-17), Gewaltprävention (S. 40), Diskriminierung (S. 33), Digitalisierung (S. 64-65) und Fundstellen S. 11, 24 gelesen; nichts zu Hass, Anfeindung oder Bedrohung im Netz, zu Meldewegen oder Plattformpflichten.', '2026-10-08', true, '{2501,2503}'),
  (25, 17, 'MV', 'keine', 'Fundstellen S. 47, 48, 52, 61, 62, 64, 69, 91 gelesen, dazu Volltextsuche nach Hass, Hetze, Anfeindung, Bedrohung, Beleidigung, digitale Gewalt, Plattform, soziale Netzwerke, Internet, Online; S. 12 (Regeln für digitale Medien) gelesen. Nichts setzt an Hass oder Anfeindung im Netz an.', '2026-10-08', true, '{2501,2503}'),
  (25, 17, 'ST', 'keine', 'Inhaltsverzeichnis, Kapitel ''Demokratie & Debatte'' (S. 11-15), ''Sicherheit durch Rechtsstaatlichkeit'' (S. 65-71) und alle sechs Fundstellen (S. 14, 37, 39, 45, 67, 71) gelesen; nichts zu Hass, Bedrohung oder Anfeindung im Netz, zu Meldewegen, Plattformpflichten oder Moderationsdesign.', '2026-10-08', true, '{2501,2503}'),
  (25, 18, null, 'massnahmen', null, '2026-10-08', true, '{2501,2502,2503}'),
  (25, 18, 'BE', 'massnahmen', null, '2026-10-08', true, '{2501,2503}'),
  (25, 18, 'MV', 'keine', 'Kapitel Medien- und Demokratiebildung (S. 6-7), Schutz/Sicherheit (S. 14-15), Diskriminierung (S. 17-18), Digitale Sicherheit (S. 44-45) gelesen; nichts zu Hass, Bedrohung oder Anfeindung im Netz. Beratungsstelle (S. 15) betrifft Gewalt, nicht Online-Hass.', '2026-10-08', true, '{2501,2503}'),
  (25, 18, 'ST', 'massnahmen', null, '2026-10-08', true, '{2501,2503}');
